class Wallet {
    private double balance = 100; // only this class can touch it directly

    public void deposit(double amount) { // any class can call this
        balance += amount;
    }

    protected double getBalanceForAudit() { // same package, plus subclasses
        return balance;
    }

    double someHelper() { // no keyword at all: package-private
        return balance / 2;
    }
}

public class Main {
    public static void main(String[] args) {
        Wallet wallet = new Wallet();
        wallet.deposit(50);
        System.out.println(wallet.getBalanceForAudit());
    }
}

