#include <iostream>
using namespace std;

class Wallet {
private:
    double balance = 100; // only this class can touch it directly

public:
    void deposit(double amount) { // any code can call this
        balance += amount;
    }

    double someHelper() { // public here; C++ protected has no package-level equivalent
        return balance / 2;
    }
};

int main() {
    Wallet wallet;
    wallet.deposit(50);
    cout << wallet.someHelper() << endl;
    return 0;
}

