class BankAccount {
    private double balance; // private: only THIS class can touch it directly

    BankAccount(double initialBalance) { // package-private constructor
        this.balance = initialBalance;
    }

    public void deposit(double amount) { // public: anyone holding a reference can call this
        balance += amount;
        System.out.println("Deposited " + amount + ", balance now " + balance);
    }

    public void withdraw(double amount) {
        if (amount > balance) {
            System.out.println("Withdrawal denied, insufficient funds");
            return;
        }
        balance -= amount;
        System.out.println("Withdrew " + amount + ", balance now " + balance);
    }

    protected double getBalanceForAudit() { // protected: visible to subclasses too
        return balance;
    }
}

class SavingsAccount extends BankAccount {
    private double interestRate;

    SavingsAccount(double initialBalance, double interestRate) {
        super(initialBalance);
        this.interestRate = interestRate;
    }

    public void applyInterest() {
        // getBalanceForAudit() is protected, visible here because SavingsAccount IS a subclass
        double interest = getBalanceForAudit() * interestRate;
        deposit(interest);
    }
}

public class Main {
    public static void main(String[] args) {
        SavingsAccount account = new SavingsAccount(1000, 0.05);
        account.deposit(500);
        account.withdraw(200);
        account.applyInterest();

        // account.balance;              // would NOT compile: balance is private to BankAccount
        // account.getBalanceForAudit();  // would NOT compile here: Main is not a subclass
    }
}

