class BankAccount:
    def __init__(self, initial_balance):
        self.__balance = initial_balance  # name-mangled, private by convention

    def deposit(self, amount):
        self.__balance += amount
        print(f"Deposited {amount}, balance now {self.__balance}")

    def withdraw(self, amount):
        if amount > self.__balance:
            print("Withdrawal denied, insufficient funds")
            return
        self.__balance -= amount
        print(f"Withdrew {amount}, balance now {self.__balance}")

    def _get_balance_for_audit(self):  # single underscore: protected by convention
        return self.__balance


class SavingsAccount(BankAccount):
    def __init__(self, initial_balance, interest_rate):
        super().__init__(initial_balance)
        self.interest_rate = interest_rate

    def apply_interest(self):
        interest = self._get_balance_for_audit() * self.interest_rate
        self.deposit(interest)


if __name__ == "__main__":
    account = SavingsAccount(1000, 0.05)
    account.deposit(500)
    account.withdraw(200)
    account.apply_interest()

