#include <iostream>
using namespace std;

class BankAccount {
private:
    double balance; // private: only THIS class can touch it directly

public:
    BankAccount(double initialBalance) : balance(initialBalance) {}

    void deposit(double amount) { // public: anyone holding the object can call this
        balance += amount;
        cout << "Deposited " << amount << ", balance now " << balance << endl;
    }

    void withdraw(double amount) {
        if (amount > balance) {
            cout << "Withdrawal denied, insufficient funds" << endl;
            return;
        }
        balance -= amount;
        cout << "Withdrew " << amount << ", balance now " << balance << endl;
    }

protected:
    double getBalanceForAudit() { // protected: visible to subclasses too
        return balance;
    }
};

class SavingsAccount : public BankAccount {
private:
    double interestRate;

public:
    SavingsAccount(double initialBalance, double interestRate)
        : BankAccount(initialBalance), interestRate(interestRate) {}

    void applyInterest() {
        double interest = getBalanceForAudit() * interestRate;
        deposit(interest);
    }
};

int main() {
    SavingsAccount account(1000, 0.05);
    account.deposit(500);
    account.withdraw(200);
    account.applyInterest();

    return 0;
}
